function logDebug(event: string, payload: Record<string, unknown>): void {
  if (!isDevelopment) {
    return;
  }

  backendRegistryLog.debug(event, payload);
}

async function pathExists(filePath: string): Promise<boolean> {
  try {
    await stat(filePath);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return false;
    }

    throw error;
  }
}

function assistantOutputForTurn(
  replay: AppServerThreadReplay,
  turnId: string,
): Array<{ type: "text"; text: string }> {
  for (let index = replay.entries.length - 1; index >= 0; index -= 1) {
    const entry = replay.entries[index];
    if (
      entry?.type === "message" &&
      entry.role === "assistant" &&
      entry.turn?.id === turnId &&
      entry.turn.status === "completed" &&
      entry.text.trim()
    ) {
      return [{ type: "text", text: entry.text }];
    }
  }

  return [];
}

type BackendClient = {
  close(): Promise<void>;
  getInitializeResult(): Promise<InitializeResult>;
  readServerCapabilities?(): Promise<CodexServerCapabilities>;
  readCodexHome?(): Promise<string>;
  readConfiguredMcpServerNames?(params?: {
    cwd?: string;
  }): Promise<string[]>;
  listThreads(
    params?: {
      archived?: boolean;
      enrichDirectories?: boolean;
      filter?: string;
      limit?: number;
      maxPages?: number;
      skipArchivedMetadataRefresh?: boolean;
    },
    diagnostics?: { callerReason?: string; ownerId?: string },
  ): Promise<AppServerThreadSummary[]>;
  listNativeSubAgentThreads?(
    params?: {
      filter?: string;
      limit?: number;
      maxPages?: number;
    },
    diagnostics?: { callerReason?: string; ownerId?: string },
  ): Promise<AppServerThreadSummary[]>;
  enrichThreadDirectories?(
    threads: AppServerThreadSummary[],
  ): Promise<AppServerThreadSummary[]>;
  archiveThread?(params: { threadId: string }): Promise<{ threadId: string }>;
  restoreThread?(params: { threadId: string }): Promise<{ threadId: string }>;
  renameThread?(params: { threadId: string; name: string }): Promise<{ threadId: string }>;
  updateThreadMetadata?(params: {
    threadId: string;
    gitInfo?: {
      branch?: string | null;
      originUrl?: string | null;
      sha?: string | null;
    } | null;
  }): Promise<{ threadId: string }>;
  updateThreadWorkspace?(params: {
    threadId: string;
    cwd: string;
  }): Promise<{ threadId: string }>;
  generateTitle?: ThreadTitleGenerator["generateTitle"];
  generateStructuredObject?(params: {
    model?: string;
    reasoningEffort?: string;
    prompt: string;
    schema: Record<string, unknown>;
    system?: string;
    isMatch: (record: Record<string, unknown>) => boolean;
    timeoutMs?: number;
  }): ReturnType<ThreadTitleGenerator["generateTitle"]>;
  listSkills(params?: {
    cwd?: string;
    cwds?: string[];
  }): Promise<AppServerListSkillsResponse["data"]>;
  onNotification(
    listener: (notification: AppServerNotification) => void | Promise<void>
  ): () => void;
  onRequest?(
    listener: (
      request: AppServerPendingRequestNotification
    ) => Promise<unknown> | unknown
  ): () => void;
  readThread(params: {
    threadId: string;
    includeTurns?: boolean;
    before?: string;
    limit?: number;
  }): Promise<AppServerReadThreadResponse["replay"]>;
  injectThreadItems?(params: { threadId: string; items: unknown[] }): Promise<void>;
  startThread(params: {
    cwd?: string;
    ephemeral?: boolean;
    model?: string;
    approvalPolicy?: string;
    sandbox?: string;
    serviceTier?: string;
    reasoningEffort?: string;
    fastMode?: boolean;
    codexEnvironmentRuntime?: CodexThreadEnvironmentRuntime;
    config?: CodexThreadStartParams["config"];
    defaultModeRequestUserInput?: boolean;
    dynamicTools?: CodexDynamicToolSpec[];
    threadSource?: CodexThreadSource;
  }): Promise<{ threadId: string }>;
  forkThread?(params: {
    threadId: string;
    path?: string;
    cwd?: string;
    model?: string;
    approvalPolicy?: string;
    sandbox?: string;
    serviceTier?: string;
    fastMode?: boolean;
    codexEnvironmentRuntime?: CodexThreadEnvironmentRuntime;
    config?: CodexThreadForkParams["config"];
  }): Promise<{ threadId: string }>;
  startTurn(params: {
    threadId: string;
    input: AppServerTurnInputItem[];
    cwd?: string;
    approvalPolicy?: string;
    sandbox?: string;
    model?: string;
    collaborationMode?: AppServerCollaborationModeRequest;
    serviceTier?: string;
    reasoningEffort?: string;
    fastMode?: boolean;
    codexEnvironmentRuntime?: CodexThreadEnvironmentRuntime;
    config?: CodexThreadStartParams["config"];
    defaultModeRequestUserInput?: boolean;
    dynamicTools?: CodexDynamicToolSpec[];
  }): Promise<{
    threadId: string;
    turnId: string;
  }>;
  recoverInvalidPersistedResponseMessageIds?(params: {
    failureMessage: string;
    forkLineageThreadIds?: string[];
    threadId: string;
  }): Promise<CodexInvalidResponseMessageIdRecoveryResult>;
  startReview?(params: {
    threadId: string;
    target: StartReviewRequest["target"];
    delivery?: StartReviewRequest["delivery"];
    model?: string;
    serviceTier?: string;
    reasoningEffort?: string;
    fastMode?: boolean;
    cwd?: string;
    codexEnvironmentRuntime?: CodexThreadEnvironmentRuntime;
    config?: CodexThreadStartParams["config"];
    dynamicTools?: CodexDynamicToolSpec[];
  }): Promise<{ threadId: string; reviewThreadId: string; turnId: string }>;
  listModels?(diagnostics?: {
    callerReason?: string;
    ownerId?: string;
  }): Promise<BackendModelOption[]>;
  readAccount?(): Promise<BackendAccountSummary>;
  readRateLimits?(): Promise<BackendRateLimitSummary[]>;
  interruptTurn(params: {
    threadId: string;
    turnId: string;
  }): Promise<{ threadId: string; turnId: string }>;
  compactThread?(params: {
    threadId: string;
  }): Promise<{ threadId: string; turnId: string; itemId?: string }>;
  listMcpServers?(params: {
    threadId?: string;
    detail: ListThreadMcpServersResponse["detail"];
  }): Promise<ListThreadMcpServersResponse["servers"]>;
  reloadMcpConfig?(): Promise<void>;
  startMcpServerOAuthLogin?(params: {
    name: string;
  }): Promise<{ authorizationUrl: string }>;
  removeMcpServer?(params: { name: string }): Promise<void>;
  steerTurn?(params: {
    threadId: string;
    input: AppServerTurnInputItem[];
    expectedTurnId: string;
  }): Promise<{ threadId: string; turnId: string }>;
  setThreadPermissions?(params: {
    threadId: string;
    cwd?: string;
    model?: string;
    approvalPolicy?: string;
    sandbox?: string;
    serviceTier?: string;
    reasoningEffort?: string;
    fastMode?: boolean;
  }): Promise<{ threadId: string }>;
  trustProject?(params: {
    projectPath: string;
    configPath?: string;
  }): Promise<{ projectPath: string; configPath?: string }>;
};

type BackendRegistryForkThreadRequest = ForkThreadRequest & {
  codexEnvironmentRuntime?: CodexThreadEnvironmentRuntime;
  onPreparedWorkspaceRollback?: (rollback: (() => Promise<void>) | undefined) => void;
  onCodexEnvironmentSetupProgress?: (
    event: CodexEnvironmentSetupProgressEvent,
  ) => void;
  sourceThreadPath?: string;
};

/**
 * Resolve the live workspace CWD for thread-scoped commands.
 *
 * Worktree threads must run from LinkedDirectorySummary.worktreePath; Local
 * threads run from LinkedDirectorySummary.path. A handoff overlay projects the
 * committed workspace change immediately. The selected workspace remains
 * authoritative across provider-side synchronization so a later stale
 * provider snapshot cannot silently restore the pre-handoff workspace.
 */
function resolveThreadWorkspaceCwd(
  thread: AppServerThreadSummary | undefined,
  overlayDirectories: AppServerThreadSummary["linkedDirectories"] = [],
): string | undefined {
  if (!thread) {
    return resolveLinkedDirectoryWorkspaceCwd(overlayDirectories);
  }

  const overlayHandoffDirectory = overlayDirectories.find(isHandoffDirectory);
  if (overlayHandoffDirectory) {
    return overlayHandoffDirectory.worktreePath ?? overlayHandoffDirectory.path;
  }

  const providerDirectories = thread.linkedDirectories.filter(
    (directory) =>
      !overlayDirectories.some((overlayDirectory) =>
        linkedDirectoriesHaveSameWorkspaceIdentity(directory, overlayDirectory),
      ),
  );

  return (
    resolveLinkedDirectoryWorkspaceCwd(providerDirectories) ??
    resolveLinkedDirectoryWorkspaceCwd(thread.linkedDirectories) ??
    resolveLinkedDirectoryWorkspaceCwd(overlayDirectories) ??
    thread.projectKey
  );
}

function resolveThreadWorkingStatePath(
  thread: Pick<AppServerThreadSummary, "projectKey" | "linkedDirectories">,
): string | undefined {
  const projectKey = thread.projectKey?.trim();
  if (projectKey) {
    return projectKey;
  }

  for (const directory of thread.linkedDirectories) {
    const worktreePath = directory.worktreePath?.trim();
    if (worktreePath) {
      return worktreePath;
    }
  }

  for (const directory of thread.linkedDirectories) {
    if (directory.kind === "local" && directory.path.trim()) {
      return directory.path.trim();
    }
  }

  return undefined;
}

// Per-worktree working state changes as the agent edits/commits, but each
// such turn pushes a fresh probe, so the background freshness window only
// needs to catch out-of-band changes (terminal/IDE edits) on the next
// snapshot. Shorter than the per-repo directory status TTL.
export const WORKTREE_WORKING_STATE_CACHE_MAX_AGE_MS = 30_000;

function isFreshThreadGitWorkingStateCacheEntry(
  entry: WorktreeGitWorkingStateCacheEntry,
  now: number,
): boolean {
  return now - entry.fetchedAt < WORKTREE_WORKING_STATE_CACHE_MAX_AGE_MS;
}

function mergedPrCommitShas(prs: PrSummary[]): string[] {
  return prs
    .filter((pr) => pr.lifecycleState === "merged" || pr.state === "merged")
    .flatMap((pr) => pr.commitShas ?? [])
    .map((sha) => sha.trim().toLowerCase())
    .filter((sha) => /^[0-9a-f]{40}$/.test(sha));
}

function linkedDirectoriesHaveSameWorkspaceIdentity(
  left: LinkedDirectorySummary,
  right: LinkedDirectorySummary,
): boolean {
  if (left.id === right.id) {
    return true;
  }

  const leftPath = normalizeLinkedDirectoryIdentityPath(left.path);
  const rightPath = normalizeLinkedDirectoryIdentityPath(right.path);
  const leftWorktreePath = normalizeLinkedDirectoryIdentityPath(left.worktreePath);
  const rightWorktreePath = normalizeLinkedDirectoryIdentityPath(right.worktreePath);
  if (leftPath && rightPath && leftPath === rightPath) {
    return leftWorktreePath === rightWorktreePath;
  }

  return Boolean(
    leftWorktreePath &&
      rightWorktreePath &&
      leftWorktreePath === rightWorktreePath,
  );
}

function normalizeLinkedDirectoryIdentityPath(
  value: string | undefined,
): string | undefined {
  const normalized = value?.trim();
  return normalized ? toDirectoryId(path.resolve(normalized)) : undefined;
}

function resolveLinkedDirectoryWorkspaceCwd(
  linkedDirectories: AppServerThreadSummary["linkedDirectories"] = [],
): string | undefined {
  const handoffDirectory = linkedDirectories.find(isHandoffDirectory);
  if (handoffDirectory) {
    return handoffDirectory.worktreePath ?? handoffDirectory.path;
  }

  const directory =
    linkedDirectories.find((candidate) => candidate.kind === "worktree") ??
    linkedDirectories.find((candidate) => candidate.kind === "local") ??
    linkedDirectories[0];

  return directory?.worktreePath ?? directory?.path;
}

function hasHandoffWorkspace(
  directories: AppServerThreadSummary["linkedDirectories"] = [],
): boolean {
  return directories.some(isHandoffDirectory);
}

function overlayHasHandoffWorkspace(
  overlay: ThreadOverlayState | undefined,
): boolean {
  return Boolean(overlay?.extraLinkedDirectories.some(isHandoffDirectory));
}

function isHandoffDirectory(directory: LinkedDirectorySummary): boolean {
  return (
    directory.id.startsWith("pwragent-handoff:") ||
    directory.id.startsWith("pwragnt-handoff:")  // legacy prefix from pre-rebrand data
  );
}

/**
 * Normalize a resolved path to forward slashes for use as a cross-platform
 * directory identifier. No-op on POSIX; on Windows turns `C:\Users\…` into
 * `C:/Users/…` so ids/keys read identically across hosts and match the
 * thread-directory-enricher's normalized identifiers.
 */
function toDirectoryId(value: string): string {
  return value.replace(/\\/g, "/");
}

function buildLocalLinkedDirectory(cwd: string | undefined): LinkedDirectorySummary[] {
  const normalized = cwd?.trim();
  if (!normalized) {
    return [];
  }
  const directoryPath = path.resolve(normalized);
  return [
    {
      id: toDirectoryId(directoryPath),
      kind: "local",
      label: path.basename(directoryPath) || directoryPath,
      path: toDirectoryId(directoryPath),
    },
  ];
}

function buildWorktreeLinkedDirectory(params: {
  repositoryPath?: string;
  worktreePath?: string;
  label?: string;
}): LinkedDirectorySummary[] {
  const normalizedWorktreePath = params.worktreePath?.trim();
  if (!normalizedWorktreePath) {
    return [];
  }

  const worktreePath = path.resolve(normalizedWorktreePath);
  const repositoryPath = path.resolve(params.repositoryPath?.trim() || worktreePath);
  const label = params.label?.trim() || path.basename(repositoryPath) || repositoryPath;

  return [
    {
      id: toDirectoryId(repositoryPath),
      kind: "worktree",
      label,
      path: toDirectoryId(repositoryPath),
      worktreePath: toDirectoryId(worktreePath),
    },
  ];
}

async function resolvePreparedRepositoryIdentityPath(params: {
  preparedPath?: string;
  requestedPath?: string;
}): Promise<string | undefined> {
  const preparedPath = params.preparedPath?.trim();
  const requestedPath = params.requestedPath?.trim();
  if (!preparedPath || !requestedPath) {
    return preparedPath || requestedPath || undefined;
  }

  const [preparedRealPath, requestedRealPath] = await Promise.all([
    realpath(preparedPath).catch(() => undefined),
    realpath(requestedPath).catch(() => undefined),
  ]);
  if (
    preparedRealPath
    && requestedRealPath
    && path.resolve(preparedRealPath) === path.resolve(requestedRealPath)
  ) {
    return requestedPath;
  }
  return preparedPath;
}

function normalizeLinkedDirectoryPathForMatch(
  value: string | undefined,
): string | undefined {
  const normalized = value?.trim();
  return normalized ? toDirectoryId(path.resolve(normalized)) : undefined;
}

function linkedDirectoriesShareWorktreeWorkspace(
  left: LinkedDirectorySummary,
  right: LinkedDirectorySummary,
): boolean {
  const normalizedLeft = normalizeLinkedDirectoryKind(left);
  const normalizedRight = normalizeLinkedDirectoryKind(right);
  if (normalizedLeft.kind !== "worktree" || normalizedRight.kind !== "worktree") {
    return false;
  }

  const leftWorktreePath = normalizeLinkedDirectoryPathForMatch(
    normalizedLeft.worktreePath,
  );
  const rightWorktreePath = normalizeLinkedDirectoryPathForMatch(
    normalizedRight.worktreePath,
  );
  return Boolean(
    leftWorktreePath
    && rightWorktreePath
    && leftWorktreePath === rightWorktreePath,
  );
}

function linkedDirectoryMatchesDetachArgs(
  directory: LinkedDirectorySummary,
  args: DetachThreadDirectoryToolArgs,
): boolean {
  if (args.directoryId?.trim() && directory.id === args.directoryId.trim()) {
    return true;
  }
  const requestedPath = normalizeLinkedDirectoryPathForMatch(args.path);
  if (
    requestedPath &&
    normalizeLinkedDirectoryPathForMatch(directory.path) === requestedPath
  ) {
    return true;
  }
  const requestedWorktreePath = normalizeLinkedDirectoryPathForMatch(args.worktreePath);
  return Boolean(
    requestedWorktreePath &&
      normalizeLinkedDirectoryPathForMatch(directory.worktreePath) ===
        requestedWorktreePath,
  );
}

function isLikelyToolManagedWorktreePath(projectKey: string | undefined): boolean {
  const normalized = projectKey?.trim();
  if (!normalized) {
    return false;
  }

  return isToolManagedWorktreePath(normalized) || /[\\/]\.worktrees[\\/]/.test(normalized);
}

function hasCachedWorktreeDirectory(
  overlay: ThreadOverlayState | undefined,
  projectPath: string,
): boolean {
  const resolvedProjectPath = path.resolve(projectPath);
  return Boolean(
    overlay?.extraLinkedDirectories.some((directory) => {
      // directory.id is forward-slash normalized; re-resolve both sides so the
      // comparison is separator-agnostic across platforms.
      if (path.resolve(directory.id) !== resolvedProjectPath) {
        return false;
      }
      return Boolean(directory.worktreePath?.trim());
    }),
  );
}

function hasEquivalentLinkedDirectory(
  overlay: ThreadOverlayState | undefined,
  directory: LinkedDirectorySummary,
): boolean {
  return Boolean(
    overlay?.extraLinkedDirectories.some((candidate) => {
      if (linkedDirectoriesShareWorktreeWorkspace(candidate, directory)) {
        return true;
      }
      if (candidate.id !== directory.id || candidate.kind !== directory.kind) {
        return false;
      }

      const candidatePath = path.resolve(candidate.path);
      const directoryPath = path.resolve(directory.path);
      const candidateWorktreePath = candidate.worktreePath?.trim()
        ? path.resolve(candidate.worktreePath)
        : undefined;
      const directoryWorktreePath = directory.worktreePath?.trim()
        ? path.resolve(directory.worktreePath)
        : undefined;

      return (
        candidatePath === directoryPath &&
        candidateWorktreePath === directoryWorktreePath
      );
    }),
  );
}

function pathContainsOrEquals(parentPath: string, childPath: string): boolean {
  const relativePath = path.relative(parentPath, childPath);
  return (
    relativePath === "" ||
    (!relativePath.startsWith("..") && !path.isAbsolute(relativePath))
  );
}

function buildCachedWorktreeDirectory(
  thread: AppServerThreadSummary,
): LinkedDirectorySummary | undefined {
  const projectKey = thread.projectKey?.trim();
  if (!projectKey) {
    return undefined;
  }

  const projectPath = path.resolve(projectKey);
  const directory = thread.linkedDirectories.find((candidate) => {
    const worktreePath = candidate.worktreePath?.trim();
    if (!worktreePath) {
      return false;
    }
    return pathContainsOrEquals(path.resolve(worktreePath), projectPath);
  });
  if (!directory) {
    return undefined;
  }

  const repositoryPath = path.resolve(directory.path);
  const worktreePath = path.resolve(directory.worktreePath!);
  if (repositoryPath === projectPath) {
    return undefined;
  }

  return {
    ...directory,
    id: toDirectoryId(projectPath),
    kind: "worktree",
    label: directory.label || path.basename(repositoryPath) || repositoryPath,
    path: toDirectoryId(repositoryPath),
    worktreePath: toDirectoryId(worktreePath),
  };
}

function buildCachedDirectoryRelationship(
  thread: AppServerThreadSummary,
): LinkedDirectorySummary | undefined {
  const worktreeDirectory = buildCachedWorktreeDirectory(thread);
  if (worktreeDirectory) {
    return worktreeDirectory;
  }

  const projectKey = thread.projectKey?.trim();
  if (!projectKey) {
    return undefined;
  }

  if (isLikelyToolManagedWorktreePath(projectKey)) {
    return undefined;
  }

  const projectPath = path.resolve(projectKey);
  const localDirectory = thread.linkedDirectories.find((candidate) => {
    if (candidate.worktreePath?.trim()) {
      return false;
    }
    return path.resolve(candidate.path) === projectPath;
  });
  if (!localDirectory) {
    return undefined;
  }

  return {
    ...localDirectory,
    id: toDirectoryId(projectPath),
    kind: "local",
    label: localDirectory.label || path.basename(projectPath) || projectPath,
    path: toDirectoryId(projectPath),
    worktreePath: undefined,
  };
}

function shouldRepairCachedDirectoryRelationship(params: {
  directory: LinkedDirectorySummary;
  overlay: ThreadOverlayState | undefined;
}): boolean {
  // The handoff overlay is both the authoritative workspace selection and the
  // durable retry marker. Keep it after Codex acknowledges the target: native
  // review can later restore the thread's original CWD in provider metadata,
  // and replacing this marker would let that stale snapshot win permanently.
  if (overlayHasHandoffWorkspace(params.overlay)) {
    return false;
  }

  if (hasEquivalentLinkedDirectory(params.overlay, params.directory)) {
    return false;
  }

  if (params.directory.kind === "worktree") {
    return true;
  }

  return Boolean(
    params.overlay?.extraLinkedDirectories.some((candidate) => {
      if (candidate.id === params.directory.id) {
        return true;
      }
      if (isHandoffDirectory(candidate)) {
        return false;
      }

      return path.resolve(candidate.path) === path.resolve(params.directory.path);
    }),
  );
}

function normalizeLinkedDirectoryKind(
  directory: LinkedDirectorySummary,
): LinkedDirectorySummary {
  if (
    directory.kind === "local" &&
    (directory.worktreePath?.trim() || isToolManagedWorktreePath(directory.path))
  ) {
    const worktreePath = directory.worktreePath?.trim() || directory.path;
    return {
      ...directory,
      kind: "worktree",
      worktreePath,
    };
  }

  return directory;
}

function linkedDirectoryIdentityKey(directory: LinkedDirectorySummary): string {
  const normalized = normalizeLinkedDirectoryKind(directory);
  const repositoryPath = path.resolve(normalized.path);
  const worktreePath = normalized.worktreePath?.trim()
    ? path.resolve(normalized.worktreePath)
    : "";
  return `${normalized.kind}:${repositoryPath}:${worktreePath}`;
}

function dedupeLinkedDirectoriesByNormalizedIdentity(
  directories: LinkedDirectorySummary[],
): LinkedDirectorySummary[] {
  const seen = new Set<string>();
  const deduped: LinkedDirectorySummary[] = [];
  for (const directory of directories) {
    const key = linkedDirectoryIdentityKey(directory);
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    deduped.push(directory);
  }
  return deduped;
}

function pendingStartedThreadMatchesFilter(
  thread: AppServerThreadSummary,
  filter: string | undefined,
): boolean {
  const normalized = filter?.trim().toLowerCase();
  if (!normalized) {
    return true;
  }
  return [
    thread.id,
    thread.title,
    thread.summary,
    thread.projectKey,
    ...thread.linkedDirectories.flatMap((directory) => [
      directory.label,
      directory.path,
      directory.worktreePath,
    ]),
  ]
    .filter(Boolean)
    .some((value) => value!.toLowerCase().includes(normalized));
}

function pendingStartedThreadWorkspaceMatches(
  thread: AppServerThreadSummary,
  pendingThread: AppServerThreadSummary,
): boolean {
  const workspaceCwd = resolveThreadWorkspaceCwd(thread)?.trim();
  const pendingWorkspaceCwd = resolveThreadWorkspaceCwd(pendingThread)?.trim();
  if (!pendingWorkspaceCwd) {
    return true;
  }
  if (!workspaceCwd) {
    return false;
  }
  if (path.resolve(workspaceCwd) !== path.resolve(pendingWorkspaceCwd)) {
    return false;
  }

  if (pendingThread.linkedDirectories.length === 0) {
    return true;
  }
  const pendingDirectoryKeys = new Set(
    pendingThread.linkedDirectories.map(linkedDirectoryIdentityKey),
  );
  return thread.linkedDirectories.some((directory) =>
    pendingDirectoryKeys.has(linkedDirectoryIdentityKey(directory))
    || pendingThread.linkedDirectories.some((pendingDirectory) =>
      linkedDirectoriesShareWorktreeWorkspace(directory, pendingDirectory),
    ),
  );
}

function retainPendingStartedThreadWorkspace(
  thread: AppServerThreadSummary,
  pendingThread: AppServerThreadSummary,
): AppServerThreadSummary {
  return {
    ...thread,
    projectKey: pendingThread.projectKey,
    linkedDirectories: pendingThread.linkedDirectories,
    gitBranch: pendingThread.gitBranch,
    codexEnvironmentRuntime:
      pendingThread.codexEnvironmentRuntime ?? thread.codexEnvironmentRuntime,
  };
}

function resolveExpectedThreadBranch(params: {
  overlay?: ThreadOverlayState;
  thread?: Pick<AppServerThreadSummary, "gitBranch">;
}): string | undefined {
  const overlayBranch = params.overlay?.gitBranch?.trim();
  if (overlayBranch) {
    return overlayBranch;
  }

  const overlayObservedBranch = params.overlay?.observedGitBranch?.trim();
  if (
    overlayObservedBranch &&
    hasHandoffWorkspace(params.overlay?.extraLinkedDirectories)
  ) {
    return overlayObservedBranch;
  }

  return params.thread?.gitBranch?.trim() || undefined;
}

function shouldUseObservedBranchForDetachedHandoff(params: {
  branch?: string;
  observedBranch?: string;
  overlay?: ThreadOverlayState;
}): boolean {
  const branch = params.branch?.trim();
  const observedBranch = params.observedBranch?.trim();
  return Boolean(
    branch === "HEAD" &&
      observedBranch &&
      observedBranch !== "HEAD" &&
      hasHandoffWorkspace(params.overlay?.extraLinkedDirectories),
  );
}

function resolveBranchDriftExpectedBranch(params: {
  observedBranch?: string;
  overlay?: ThreadOverlayState;
  requestedExpectedBranch?: string;
  thread?: Pick<AppServerThreadSummary, "gitBranch">;
}): { expectedBranch?: string; repairedDetachedHandoffBranch: boolean } {
  const overlayBranch = params.overlay?.gitBranch?.trim();
  if (
    shouldUseObservedBranchForDetachedHandoff({
      branch: overlayBranch,
      observedBranch: params.observedBranch,
      overlay: params.overlay,
    })
  ) {
    return {
      expectedBranch: params.observedBranch,
      repairedDetachedHandoffBranch: true,
    };
  }
  if (overlayBranch) {
    return {
      expectedBranch: overlayBranch,
      repairedDetachedHandoffBranch: false,
    };
  }

  const requestedBranch = params.requestedExpectedBranch?.trim();
  if (
    shouldUseObservedBranchForDetachedHandoff({
      branch: requestedBranch,
      observedBranch: params.observedBranch,
      overlay: params.overlay,
    })
  ) {
    return {
      expectedBranch: params.observedBranch,
      repairedDetachedHandoffBranch: true,
    };
  }
  if (requestedBranch) {
    return {
      expectedBranch: requestedBranch,
      repairedDetachedHandoffBranch: false,
    };
  }

  const fallbackBranch = resolveExpectedThreadBranch({
    overlay: params.overlay,
    thread: params.thread,
  });
  if (
    shouldUseObservedBranchForDetachedHandoff({
      branch: fallbackBranch,
      observedBranch: params.observedBranch,
      overlay: params.overlay,
    })
  ) {
    return {
      expectedBranch: params.observedBranch,
      repairedDetachedHandoffBranch: true,
    };
  }

  return {
    expectedBranch: fallbackBranch,
    repairedDetachedHandoffBranch: false,
  };
}

async function readCurrentGitBranch(sourcePath: string): Promise<string | undefined> {
  const result = await execFile(
    "git",
    ["-C", sourcePath, "rev-parse", "--abbrev-ref", "HEAD"],
    { env: buildPwrAgentChildProcessEnv(process.env) },
  );
  const branch = result.stdout.trim();
  return branch || undefined;
}

function normalizeHandoffTaskCwd(cwd: string | undefined): string | undefined {
  const trimmed = cwd?.trim();
  if (!trimmed) {
    return undefined;
  }
  if (trimmed === "~") {
    return os.homedir();
  }
  if (trimmed.startsWith("~/") || trimmed.startsWith("~\\")) {
    return path.join(os.homedir(), trimmed.slice(2));
  }
  return trimmed;
}

function sameResolvedPath(
  left: string | undefined,
  right: string | undefined,
): boolean {
  if (!left?.trim() || !right?.trim()) {
    return false;
  }
  return path.resolve(left) === path.resolve(right);
}

function shouldInheritHandoffCodexEnvironmentRuntime(params: {
  callerCwd?: string;
  callerProjectBoundary?: string;
  requestedCwd?: string;
  requestedProjectBoundary?: string;
  workspaceMode: HandoffTaskWorkspaceMode;
}): boolean {
  if (params.workspaceMode === "none") {
    return false;
  }
  return (
    !params.requestedCwd
    || sameResolvedPath(params.requestedCwd, params.callerCwd)
    || (
      Boolean(params.callerProjectBoundary)
      && Boolean(params.requestedProjectBoundary)
      && sameResolvedPath(
        params.callerProjectBoundary,
        params.requestedProjectBoundary,
      )
    )
  );
}

function sameHandoffProjectBoundary(
  left: string | undefined,
  right: string | undefined,
): boolean {
  if (!left?.trim() || !right?.trim()) {
    return true;
  }
  return sameResolvedPath(left, right);
}

function linkedDirectoryMatchesCwd(
  directory: LinkedDirectorySummary,
  cwd: string,
): boolean {
  const resolvedCwd = path.resolve(cwd);
  return (
    path.resolve(directory.worktreePath ?? directory.path) === resolvedCwd ||
    path.resolve(directory.path) === resolvedCwd
  );
}

function directoryContainsPath(
  directoryPath: string | undefined,
  targetPath: string,
): boolean {
  if (!directoryPath?.trim()) {
    return false;
  }
  const relative = path.relative(path.resolve(directoryPath), targetPath);
  return (
    relative === "" ||
    (!!relative && !relative.startsWith("..") && !path.isAbsolute(relative))
  );
}

const HANDOFF_CWD_TRUST_QUESTION_ID = "trust_directory";
const HANDOFF_CWD_TRUST_APPROVE_LABEL = "Trust directory (Recommended)";

function linkedDirectoryActiveWorkspaceCoversCwd(
  directory: LinkedDirectorySummary,
  cwd: string,
): boolean {
  const resolvedCwd = path.resolve(cwd);
  const activeDirectoryPath =
    directory.kind === "worktree" ? directory.worktreePath : directory.path;
  return directoryContainsPath(activeDirectoryPath, resolvedCwd);
}

function linkedDirectoriesActiveWorkspaceCoversCwd(params: {
  cwd: string;
  overlay?: ThreadOverlayState;
  thread?: Pick<AppServerThreadSummary, "linkedDirectories">;
}): boolean {
  return [
    ...(params.overlay?.extraLinkedDirectories ?? []),
    ...(params.thread?.linkedDirectories ?? []),
  ].some((directory) =>
    linkedDirectoryActiveWorkspaceCoversCwd(directory, params.cwd),
  );
}

type PullRequestRepositoryRef = {
  provider: string;
  org: string;
  repo: string;
  urlBase?: string;
};

type PullRequestReferenceIdentity = PullRequestRepositoryRef & {
  number: number;
  url: string;
};

function parsePullRequestReferenceUrl(
  value: string | undefined,
): PullRequestReferenceIdentity | undefined {
  const trimmed = value?.trim();
  if (!trimmed) {
    return undefined;
  }
  let parsed: URL;
  try {
    parsed = new URL(trimmed);
  } catch {
    return undefined;
  }
  const segments = parsed.pathname.split("/").filter(Boolean);
  const markerIndex = segments.findIndex(
    (segment) => segment === "pull" || segment === "merge_requests",
  );
  if (markerIndex <= 0 || markerIndex >= segments.length - 1) {
    return undefined;
  }
  const number = Number.parseInt(segments[markerIndex + 1] ?? "", 10);
  if (!Number.isInteger(number) || number <= 0) {
    return undefined;
  }
  const repoIndex = segments[markerIndex - 1] === "-"
    ? markerIndex - 2
    : markerIndex - 1;
  if (repoIndex <= 0) {
    return undefined;
  }
  const org = segments.slice(0, repoIndex).join("/");
  const repo = segments[repoIndex];
  if (!org || !repo) {
    return undefined;
  }
  return {
    provider: normalizePullRequestProvider(parsed.hostname),
    org,
    repo,
    number,
    url: trimmed,
    urlBase: `${parsed.protocol}//${parsed.host}`,
  };
}

function parseGitRemoteRepositoryUrl(
  value: string | undefined,
): PullRequestRepositoryRef | undefined {
  const trimmed = value?.trim();
  if (!trimmed) {
    return undefined;
  }
  const sshMatch = /^git@([^:]+):(.+)$/.exec(trimmed);
  const rawPath = sshMatch ? sshMatch[2] : undefined;
  const provider = sshMatch?.[1]
    ? normalizePullRequestProvider(sshMatch[1])
    : undefined;
  if (rawPath && provider) {
    return parseGitRemotePath(provider, rawPath, `https://${provider}`);
  }
  try {
    const parsed = new URL(trimmed);
    return parseGitRemotePath(
      normalizePullRequestProvider(parsed.hostname),
      parsed.pathname,
      `${parsed.protocol}//${parsed.host}`,
    );
  } catch {
    return undefined;
  }
}

function parseGitRemotePath(
  provider: string,
  rawPath: string,
  urlBase: string,
): PullRequestRepositoryRef | undefined {
  const segments = rawPath
    .replace(/^\/+/, "")
    .replace(/\.git$/i, "")
    .split("/")
    .filter(Boolean);
  if (segments.length < 2) {
    return undefined;
  }
  const repo = segments.at(-1);
  const org = segments.slice(0, -1).join("/");
  if (!org || !repo) {
    return undefined;
  }
  return { provider, org, repo, urlBase };
}

function pullRequestRepositoryKey(ref: PullRequestRepositoryRef): string {
  return `${normalizePullRequestProvider(ref.provider)}/${ref.org.toLowerCase()}/${ref.repo.toLowerCase()}`;
}

function buildPullRequestReferenceUrl(ref: PullRequestRepositoryRef & { number: number }): string {
  const provider = normalizePullRequestProvider(ref.provider);
  const base = ref.urlBase?.replace(/\/+$/, "") || `https://${provider}`;
  const encodedPath = [...ref.org.split("/"), ref.repo]
    .map((part) => encodeURIComponent(part))
    .join("/");
  const marker = provider.includes("gitlab")
    ? "-/merge_requests"
    : "pull";
  return `${base}/${encodedPath}/${marker}/${ref.number}`;
}

function normalizePositivePullRequestNumber(value: unknown): number | undefined {
  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    return undefined;
  }
  return value;
}

